  it.todo("should return an empty grid for an empty grid — []");
  it.todo("should kill a single live cell with 0 neighbors — [(0,0)] becomes []");
  it.todo("Rule 1 Underpopulation: should kill both cells that each have 1 neighbor — [(0,1), (1,1)] becomes []");
