  it.todo("Rule 3 Overpopulation: center cell (1,1) with 4 live neighbors dies — 3x3 grid without corners-of-middle-row becomes [(0,0),(2,0),(0,1),(2,1),(0,2),(2,2)]");
  it.todo("Rule 4 Reproduction: dead cell (1,1) with exactly 3 live neighbors becomes alive — [(0,0),(1,0),(0,1)] becomes [(0,0),(1,0),(0,1),(1,1)]");
  it.todo("Block still life: should stay unchanged — [(0,0),(1,0),(0,1),(1,1)] becomes [(0,0),(1,0),(0,1),(1,1)]");
  it.todo("Blinker: vertical becomes horizontal — [(0,0),(0,1),(0,2)] becomes [(-1,1),(0,1),(1,1)]");
  it.todo("Blinker: horizontal becomes vertical again after second generation — [(-1,1),(0,1),(1,1)] becomes [(0,0),(0,1),(0,2)]");
});

